#include <algorithm>
#include <vector>
#include <random>
#include <chrono>
#include <cstddef>
#include <utility>
#include <iostream>
#include <iomanip>

// Custom QuickSort from the question
void quicksort_custom(double* a, std::size_t n) {
    while (n > 1) {
        const double pivot = a[n / 2];
        std::size_t lo = 0, i = 0, hi = n;
        while (i < hi) {
            if (a[i] < pivot) {
                std::swap(a[lo++], a[i++]);
            } else if (a[i] > pivot) {
                std::swap(a[i], a[--hi]);
            } else {
                ++i;
            }
        }
        if (lo < n - hi) {
            quicksort_custom(a, lo);
            a += hi;
            n -= hi;
        } else {
            quicksort_custom(a + hi, n - hi);
            n = lo;
        }
    }
}

